function 工作簿信息() {
  const wb = ActiveWorkbook;
  console.log(wb.Name);
  console.log(wb.FullName);
  console.log(wb.Path);
}

function 保存() {
  const wb = ActiveWorkbook;
  if (wb.Path === "") {
    alert("新文件还没保存过，请手动另存");
    return;
  }
  wb.Save();
}

function 数据块() {
  const s = Sheets.Item(1);
  const r = s.Range("A1").CurrentRegion;
  console.log(r.Address);
  console.log(r.Rows.Count, r.Columns.Count);
}

function 遍历块() {
  const s = Sheets.Item(1);
  const r = s.Range("A1").CurrentRegion;
  for (let i = 2; i <= r.Rows.Count; i++) {
    console.log(s.Range("A" + i).Value2);
  }
}

function 最后一行() {
  const s = Sheets.Item(1);
  const last = s.Range("A1048576").End(-4162).Row;
  console.log(last);
}

function 最后一列() {
  const s = Sheets.Item(1);
  const col = s.Range("A1").End(-4161).Column;
  console.log(col);
}

function 自动列宽() {
  const s = Sheets.Item(1);
  s.Range("A:C").Columns.AutoFit();
}

function 自动行高() {
  const s = Sheets.Item(1);
  s.Range("1:3").Rows.AutoFit();
}

function 复制() {
  const s = Sheets.Item(1);
  s.Range("A1:B3").Copy(s.Range("D1"));
}

function 只粘值() {
  const s = Sheets.Item(1);
  s.Range("A1:A3").Copy();
  s.Range("C1").PasteSpecial(-4163);
  Application.CutCopyMode = 0;
}

function 建图() {
  const s = Sheets.Item(1);
  const co = s.ChartObjects.Add(200, 20, 320, 220);
  co.Chart.SetSourceData(s.Range("A1:B4"));
  co.Chart.ChartType = 51;
}

function 改标题() {
  const s = Sheets.Item(1);
  const co = s.ChartObjects.Item(1);
  co.Chart.HasTitle = true;
  co.Chart.ChartTitle.Text = "月度销量";
}

function 刷新透视() {
  const s = Sheets.Item(1);
  const n = s.PivotTables.Count;
  for (let i = 1; i <= n; i++) {
    s.PivotTables.Item(i).RefreshTable();
  }
  console.log("刷新了 " + n + " 个");
}

function 看字段() {
  const s = Sheets.Item(1);
  const pt = s.PivotTables.Item(1);
  const fs = pt.PivotFields;
  for (let i = 1; i <= fs.Count; i++) {
    console.log(fs.Item(i).Name);
  }
}

function 录入() {
  const s = Sheets.Item(1);
  const v = InputBox("请输入姓名", "录入", "张三");
  if (!v) {
    return;
  }
  s.Range("A1").Value2 = v;
}

function 加一() {
  const v = InputBox("输入一个数字", "加一", "10");
  if (v === "") {
    return;
  }
  alert(Number(v) + 1);
}

function 确认删除() {
  const s = Sheets.Item(1);
  const r = MsgBox("确定删除第 2 行吗？", 4, "确认");
  if (r === 6) {
    s.Rows.Item(2).Delete();
  }
}

function 提示() {
  MsgBox("处理完成", 0, "提示");
}

function 汇总() {
  alert("汇总完成");
}

function 入口() {
  Application.Run("汇总");
}

function 平方(n) {
  return n * n;
}

function 调用() {
  const v = Application.Run("平方", 5);
  alert(v);
}
